import re, os, subprocess

root = '.'
results = []  # (file, timer_callback, lock_expr, line)

# Step 1: find all timer callback names registered via timer_setup/setup_timer
cb_names = {}  # name -> (file, regline)
reg_re = re.compile(r'(timer_setup|setup_timer)\s*\(\s*[^,]+,\s*([A-Za-z_0-9]+)\s*,')
for dirpath, dirs, files in os.walk(root):
    dirs[:] = [d for d in dirs if d not in ('.git',)]
    for f in files:
        if not f.endswith('.c') and not f.endswith('.h'):
            continue
        p = os.path.join(dirpath, f)
        try:
            with open(p, 'r', errors='replace') as fh:
                for i, line in enumerate(fh, 1):
                    m = reg_re.search(line)
                    if m:
                        cb_names.setdefault(m.group(2), []).append((p, i))
        except Exception:
            pass

print("timer callbacks registered:", len(cb_names))

# Step 2: extract function bodies for those callbacks, find plain spin_lock (not _bh/_irqsave/_irq/_nested/_irqsave_nested)
def find_bodies(path, names):
    out = {}
    try:
        src = open(path, errors='replace').read()
    except Exception:
        return out
    for name in names:
        # find definition: name( ... ) { ... } - match any whitespace
        pat = re.compile(r'\b' + re.escape(name) + r'\s*\([^;{]*?\)\s*\{', re.S)
        for m in pat.finditer(src):
            # walk braces
            i = m.end() - 1
            depth = 0
            j = i
            while j < len(src):
                if src[j] == '{': depth += 1
                elif src[j] == '}':
                    depth -= 1
                    if depth == 0: break
                j += 1
            body = src[i:j+1]
            startline = src[:m.start()].count('\n') + 1
            out.setdefault(name, []).append((body, startline))
    return out

lock_re = re.compile(r'spin_lock\s*\(\s*(&[^)]+)\)')
bh_guard = re.compile(r'local_bh_disable|spin_lock_bh|spin_lock_irqsave|spin_lock_irq|local_irq_save|local_irq_disable')

for name, regs in sorted(cb_names.items()):
    files = set(r[0] for r in regs)
    for path in files:
        bodies = find_bodies(path, [name])
        for body, startline in bodies.get(name, []):
            for lm in lock_re.finditer(body):
                line_no = startline + body[:lm.start()].count('\n')
                # check for bh guard in body before this lock
                pre = body[:lm.start()]
                results.append((path, name, lm.group(1), line_no))

print("plain spin_lock sites inside timer callbacks:", len(results))
for r in sorted(set(results)):
    print("  %s:%d  %s  %s" % (r[0], r[3], r[1], r[2]))
